const BINDUNGEN = {
  privat_drive_inbox: "privat",
  privat_mail: "privat",
  privat_manual_upload: "privat",
  visolva_sharepoint_inbox: "arbeitgeber_visolva",
  visolva_mail: "arbeitgeber_visolva",
  visolva_manual_upload: "arbeitgeber_visolva"
};
const REGISTER = ["privat", "arbeitgeber_visolva"];
const SCHEMA = { privat: "jarvis_privat", arbeitgeber_visolva: "jarvis_visolva" };
const CREDENTIAL = { privat: "jv_privat_postgres", arbeitgeber_visolva: "jv_visolva_postgres" };
const ergebnis = [];
for (const item of $input.all()) {
  const bindung = item.json.source_binding;
  const hinweis = item.json.context_id_hint;
  const aufgeloest = Object.prototype.hasOwnProperty.call(BINDUNGEN, bindung) ? BINDUNGEN[bindung] : null;
  let ok = true;
  let grund = "";
  if (!bindung) { ok = false; grund = "source_binding fehlt"; }
  else if (aufgeloest === null) { ok = false; grund = "source_binding nicht registriert: " + bindung; }
  else if (REGISTER.indexOf(aufgeloest) === -1) { ok = false; grund = "Kontext nicht im Register: " + aufgeloest; }
  else if (hinweis && hinweis !== aufgeloest) { ok = false; grund = "context_id_hint widerspricht der Bindung"; }
  ergebnis.push({ json: {
    resolved: ok,
    context_id: ok ? aufgeloest : null,
    db_schema: ok ? SCHEMA[aufgeloest] : null,
    credential_ref: ok ? CREDENTIAL[aufgeloest] : null,
    resolution_method: "source_binding",
    source_binding: bindung || null,
    reason: grund,
    trace_id: item.json.trace_id || null
  } });
}
return ergebnis;
